import type {
  PerformanceAndBreakdownInnovationStageValue,
  PerformanceAndBreakdownWaterfallData,
} from '../../types';

const STAGE_VALUE_MULTIPLIERS: Record<
  PerformanceAndBreakdownInnovationStageValue,
  number
> = {
  y1: 1,
  y2: 0.92,
  y3: 1.08,
  y4: 1.14,
  y5: 1.2,
};

function formatScaledValue(value: number): string {
  const rounded = Math.round(value * 10) / 10;
  const prefix = rounded > 0 ? '+' : '';
  return `${prefix}${rounded}`;
}

function isFloatingBarIndex(
  index: number,
  first: number,
  last: number,
  retained?: number,
): boolean {
  if (index <= first || index >= last) {
    return false;
  }

  return retained === undefined || index !== retained;
}

export function applyInnovationStageToDeepDiveMock(
  baseMock: PerformanceAndBreakdownWaterfallData,
  stage: PerformanceAndBreakdownInnovationStageValue,
): PerformanceAndBreakdownWaterfallData {
  const multiplier = STAGE_VALUE_MULTIPLIERS[stage];
  const first = baseMock.specialIndexes?.first ?? 0;
  const last = baseMock.specialIndexes?.last ?? baseMock.values.length - 1;
  const retained = baseMock.specialIndexes?.retained;

  const values = baseMock.values.map((value, index) => {
    if (!isFloatingBarIndex(index, first, last, retained)) {
      return value;
    }

    return Math.round(value * multiplier * 10) / 10;
  });

  const formattedRow = baseMock.formattedData[0]?.map(
    (formattedValue, index) => {
      if (!isFloatingBarIndex(index, first, last, retained)) {
        return formattedValue;
      }

      return formatScaledValue(values[index]);
    },
  );

  return {
    ...baseMock,
    values,
    formattedData: formattedRow ? [formattedRow] : baseMock.formattedData,
  };
}
